#!/bin/bash
IFS=. read -r a b c d <<< "$1"; mask=$((0xFFFFFFFF << (32 - $2))); net=$(( ( (a<<24) + (b<<16) + (c<<8) + d ) & mask )); broad=$(( net | ~mask & 0xFFFFFFFF )); printf "%d.%d.%d.%d - %d.%d.%d.%d" $(( (net+1) >> 24 & 255 )) $(( (net+1) >> 16 & 255 )) $(( (net+1) >> 8 & 255 )) $(( (net+1) & 255 )) $(( (broad-1) >> 24 & 255 )) $(( (broad-1) >> 16 & 255 )) $(( (broad-1) >> 8 & 255 )) $(( (broad-1) & 255 ))
